## 2. Update main.ts - Register Toast Plugin

```ts src/main.ts
import './assets/main.css'

import { createApp, onBeforeMount, onBeforeUnmount, watch } from 'vue'
import store, { $storex } from "./store"
import service from "./service"

import App from './App.vue'
import Modal from './components/Modal.vue'
import Toast from './components/Toast.vue'
import router from './router'
import Markdown from '@/components/Markdown.vue'

import 'vuefinder/dist/style.css'
import VueFinder from 'vuefinder/dist/vuefinder'

// BUG: error loading module. Keep it here
import highlightjs from 'highlight.js'

// Monaco editor
import editorWorker from 'monaco-editor/esm/vs/editor/editor.worker?worker'
import jsonWorker from 'monaco-editor/esm/vs/language/json/json.worker?worker'
import cssWorker from 'monaco-editor/esm/vs/language/css/css.worker?worker'
import htmlWorker from 'monaco-editor/esm/vs/language/html/html.worker?worker'
import tsWorker from 'monaco-editor/esm/vs/language/typescript/ts.worker?worker'

self.MonacoEnvironment = {
  getWorker(_, label) {
    if (label === 'json') {
      return new jsonWorker()
    }
    if (label === 'css' || label === 'scss' || label === 'less') {
      return new cssWorker()
    }
    if (label === 'html' || label === 'handlebars' || label === 'razor') {
      return new htmlWorker()
    }
    if (label === 'typescript' || label === 'javascript') {
      return new tsWorker()
    }
    return new editorWorker()
  },
}

function generateUID(length) {
  return window.btoa(String.fromCharCode(...window.crypto.getRandomValues(new Uint8Array(length * 2)))).replace(/[+/=]/g, "").substring(0, length)
}

const globalMixin = {
  onBeforeMount() {
    console.log("Before mount. Events: ", this.events, this.$root)
  },
  onBeforeUnmount() {
    console.log("Before Unmount. Events: ", this.events)
  },
  computed: {
    $storex () {
      return $storex
    },
    $ui () {
      return $storex.ui
    },
    $views () {
      return $storex.views
    },
    $projects () {
      return $storex.projects
    },
    $app () {
      const tabId = this.$props?.params?.params?.app?.tabId
      if (!tabId) return null
      return $storex.ui.openApps[tabId]
    },
    $projectId() {
      return this.$app?.params?.project_id ||
             this.$props?.params?.params?.app?.params?.project_id
    },
    $project () {
      return $storex.projects.allProjectsById[this.$projectId] ||
             $storex.projects.activeProject
    },
    $session () {
      return $storex.session
    },
    $user () {
      return $storex.api.user
    },
    $users () {
      return $storex.users
    },
    $chats () {
      return $storex.chats
    },
    $teams () {
      return $storex.teams
    },
    $media () {
      return $storex.media
    },
    $globalSettings() {
      return $storex.api.globalSettings
    },
    $service () {
      return service
    },
  },
  watch: {
  },
  methods: {
    $bubble(event: string, data: EventInit) {
    },
    generateUID
  }
}

$storex.users.login()

const app = createApp(App)
              .mixin(globalMixin)
              .use(store)
              .use(router)
              .use(VueFinder)
              .component('modal', Modal)
              .component('Markdown', Markdown)
              .component('Toast', Toast)
              .mount('#app')

// ADDED: Register toast plugin globally
let toastInstance = null
app.config.globalProperties.$toast = {
  success: (msg, duration) => toastInstance?.success(msg, duration),
  error: (msg, duration) => toastInstance?.error(msg, duration),
  warning: (msg, duration) => toastInstance?.warning(msg, duration),
  info: (msg, duration) => toastInstance?.info(msg, duration),
  clear: () => toastInstance?.clear()
}

$storex.app = app
$storex.$router = router
$storex.setToastInstance = (instance) => {
  toastInstance = instance
}

// eruda for mobile debugging
window.setTimeout(() =>
  (function() {
    function isMobile() {
      return /Mobi|Android/i.test(navigator.userAgent)
    }
    if (isMobile()) {
      var script1 = document.createElement('script')
      script1.src = "https://cdn.jsdelivr.net/npm/eruda"
      document.body.appendChild(script1)
    }
  })(), 10)
