        class="btn btn-sm btn-primary"
        :disabled="!pendingMedias.length || uploading"
        :class="uploading ? 'loading' : ''"
        @click="uploadAll"
      >
        <i v-if="!uploading" class="fa-solid fa-cloud-arrow-up mr-1"></i>
        {{ uploading ? 'Uploading...' : 'Upload All' }}
      </button>
    </div>
