      Object.assign(this.form, updates)
    },
    goToSection(section) {
      this.activeSection = section
    },
    nextSection() {
      const sections = ['workspace', 'basic', 'configure']
      const idx = sections.indexOf(this.activeSection)
      if (idx < sections.length - 1) {
        this.activeSection = sections[idx + 1]
      }
    },
    previousSection() {
      const sections = ['workspace', 'basic', 'configure']
      const idx = sections.indexOf(this.activeSection)
      if (idx > 0) {
        this.activeSection = sections[idx - 1]
      }
    },
    resetForm() {
      if (confirm('Reset all fields?')) {
        this.form = {
          name: '',
          description: '',
          folder_path: '',
          template: '',
          project_ids: [],
          user_ids: [],
          apps: [{
            name: 'App',
            icon: 'fa-globe',
            path: '/app',
            port: 3000,
            roles: ['admin'],
            is_vnc: false,
            scheme: 'http'
          }],
          resources: {
            cpus: '',
            memory: '',
            shm_size: '512m'
          },
          use_sysbox: false
        }
        this.activeSection = 'workspace'
      }
    },
    async createWorkspace() {
      if (!this.isFormValid) return
      this.isCreating = true
      try {
        const workspace = await this.theProject.$api.projects.workspaces.create({
          ...this.form,
          status: 'stopped'
        })
        this.$toast.success(`Workspace "${workspace.name}" created successfully`)
        this.$emit('created', workspace)
      } catch (error) {
        this.$toast.error(`Failed to create workspace: ${error.message}`)
        console.error(error)
      } finally {
        this.isCreating = false
      }
    }
  }
}
</script>
