    return {
      files: [],
      selectedFile: null,
      fileContent: '',
      loadingFiles: false,
      loadingContent: false,
      showNewFileInput: false,
      newFileName: ''
    }
  },
  computed: {
    theProject() {
      return this.project || this.$project
    },
    workspaceFilePath() {
      return this.selectedFile ? `workspace/${this.selectedFile}` : ''
    },
    fileLanguage() {
      if (!this.selectedFile) return 'yaml'
      const ext = this.selectedFile.split('.').pop()
      const map = { yaml: 'yaml', yml: 'yaml', json: 'json', sh: 'bash', md: 'markdown', txt: 'text', env: 'bash' }
      return map[ext] || ext
    }
  },
  async mounted() {
    await this.loadFiles()
  },
  methods: {
    async loadFiles() {
      this.loadingFiles = true
      try {
        const result = await this.theProject.$api.projects.workspaces.files.list(this.workspace.id)
        this.files = Array.isArray(result) ? result : (result.files || [])
      } catch (error) {
        console.error('Failed to list workspace files', error)
        this.$toast.error('Failed to load workspace files')
        this.files = []
      } finally {
        this.loadingFiles = false
      }
    },

    async openFile(fileName) {
      if (this.selectedFile === fileName) return
      this.selectedFile = fileName
      this.fileContent = ''
      this.loadingContent = true
      try {
        const result = await this.theProject.$api.projects.workspaces.files.read(this.workspace.id, fileName)
        this.fileContent = result.content || result || ''
      } catch (error) {
        console.error('Failed to read workspace file', error)
        this.$toast.error(`Failed to load file: ${error.message}`)
        this.fileContent = `# Error loading file: ${error.message}`
      } finally {
        this.loadingContent = false
      }
    },

    async onSaveFile({ file, content }) {
      const realFile = this.selectedFile
      try {
        await this.theProject.$api.projects.workspaces.files.write(this.workspace.id, realFile, content)
        await this.loadFiles()
        this.$toast.success('File saved successfully')
      } catch (error) {
        console.error('Failed to save workspace file', error)
        this.$toast.error(`Failed to save file: ${error.message}`)
      }
    },

    async createNewFile() {
      if (!this.newFileName.trim()) return
      const name = this.newFileName.trim()
      try {
        await this.theProject.$api.projects.workspaces.files.write(this.workspace.id, name, '')
        this.showNewFileInput = false
        this.newFileName = ''
        await this.loadFiles()
        await this.openFile(name)
        this.$toast.success(`File "${name}" created`)
      } catch (error) {
        console.error('Failed to create file', error)
        this.$toast.error(`Failed to create file: ${error.message}`)
      }
    }
  }
}
